import logging
from logging.handlers import MemoryHandler

def rec(label, level):
    return logging.LogRecord(label, level, "sample.py", 1, label, (), None)

def labels(records):
    return [r.name for r in records]

class Tap:
    def __init__(self):
        self.received = []
        self.flushes = 0
        self.closes = 0

    def handle(self, r):
        self.received.append(r)
        return True

    def flush(self):
        self.flushes += 1

    def close(self):
        self.closes += 1

def outcome(f):
    try:
        f()
        return "ok"
    except Exception as exc:
        return type(exc).__name__

def describe(x):
    if isinstance(x, logging.LogRecord):
        return x.name
    return x

